/* Scrolls the UV offsets of count overlay layers (wrapping into [-1, 1]) and, for each one in view, queues its two-texture GS setup and draws it.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l01/gameplay/entities/002b96e0.c, FUN_L01_002b96e0. */
void func_L01_002BA898_r(s32 count, ScrollLayer_2BA898 *l) {
    struct DmaTag_2BA898 *tag;
    u64 *q;
    s32 vis;
    s32 i;

    for (i = 0; i < count; i++, l++) {
        l->u0 += l->du0 * l->rate0;
        l->v0 += l->dv0 * l->rate0;
        if (l->u0 > 1.0f)
            l->u0 -= 1.0f;
        else if (l->u0 < -1.0f)
            l->u0 += 1.0f;
        if (l->v0 > 1.0f)
            l->v0 -= 1.0f;
        else if (l->v0 < -1.0f)
            l->v0 += 1.0f;
        l->u1 += l->du1 * l->rate1;
        l->v1 += l->dv1 * l->rate1;
        if (l->u1 > 1.0f)
            l->u1 -= 1.0f;
        else if (l->u1 < -1.0f)
            l->u1 += 1.0f;
        if (l->v1 > 1.0f)
            l->v1 -= 1.0f;
        else if (l->v1 < -1.0f)
            l->v1 += 1.0f;
        l->frame = (l->frame + l->frame_step) & 0xFFFFFF;
        vis = FastBSphereCheck_r(l->bounds, 400.0f);
        if (vis == -1)
            continue;
        l01_packet_r.tag->tag = 0x30000007;
        l01_packet_r.tag->addr = (u32)water_setup_dma_block_r;
        l01_packet_r.tag->vif0 = 0;
        l01_packet_r.tag->vif1 = 0x50000007;
        l01_packet_r.tag++;
        l01_packet_r.tag->tag = 0x10000005;
        l01_packet_r.tag->addr = 0;
        l01_packet_r.tag->vif0 = 0;
        l01_packet_r.tag->vif1 = 0x50000005;
        tag = l01_packet_r.tag;
        q = (u64 *)(tag + 1);
        l01_packet_r.tag = tag + 1;
        q[0] = 0x4000000000008001;
        q[1] = 0xEEEE;
        q[2] = ((u64)l->alpha0 << 32) | 100;
        q[3] = 0x42;
        q[4] = ((u64)l->alpha1 << 32) | 100;
        q[5] = 0x43;
        q[6] = GetEffectTex_r(l->tex0);
        q[7] = 6;
        q[8] = GetEffectTex_r(l->tex1);
        q[9] = 7;
        l01_packet_r.tag = tag + 6;
        build_overlay_layer_wave_vertices_r(l);
        emit_textured_strip_packet_r(l->shape, 0x70000000, 0x70003000, 0x70001000, 0x70002000, 1 - vis);
    }
}
