/* Spawns three bursts of sparks around a moby with random velocity, colours and size. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/l01/unclassified_002b96e0.c, FUN_L01_002e6518. */
void spawn_birdbot_movement_particles(SplashMoby *m, u128 *origin) {
    Vec4 base;
    Vec4 vel;
    Vec4 tmp;
    Vec4 rel;
    SplashColors inner;
    SplashColors outer;
    Vec4 *bp;
    unsigned int *c1;
    unsigned int *c2;
    float size;
    int i;

    base.q = *origin;
    bp = &base;
    for (i = 2; i >= 0; i--) {
        tmp.q = 0;
        tmp.f[0] = random_float_between(1.0f, -1.0f) * (g_frame_time * 0.2f);
        tmp.f[1] = random_float_between(1.0f, -1.0f) * (g_frame_time * 0.2f);
        tmp.f[2] = random_float_between(0.8f, 1.2f) * (g_frame_time * -7.0f);
        vel.q = tmp.q;
        inner = novalis_birdbot_splash_inner_colors;
        outer = novalis_birdbot_splash_outer_colors;
        Moby_GetJointWorldPos(m, 1, &tmp);
        matrix_mul_vec3(&vel, &vel, m->mtx);
        FastVecSub(&rel, &m->pos, bp);
        FastVecAdd(&vel, &vel, &rel);
        c1 = &inner.c[random_integer_below(6)];
        c2 = &outer.c[random_integer_below(6)];
        size = random_float_between(105000.0f, 157500.0f);
        PartType22Spawn(&tmp, &vel, *c1, *c2, size, scale_ticks(rand_range(5, 0xF)));
    }
}
