/* Picks the path node the follower should head for: an ordered path just steps to the next stop; otherwise the nearest node and its two neighbours are scored (distance, or heading change for slow movers) and the best one is written to *idx. Returns nonzero when the pick differs from the nearest node.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l01/gameplay/entities/002b96e0.c, FUN_L01_002e6790. */
int select_birdbot_path_node(void *arg, int *idx) {
    Moby *m = arg;
    PathPickTarget target;
    Vec4 pt;
    PathPickVars *v;
    PathFollow *f;
    s32 fast;
    s32 prev;
    s32 next;
    s32 best;
    s32 last;
    s32 i;
    f32 d;
    f32 a;
    f32 best_d;
    f32 best_a;
    f32 r;
    f32 dist;

    v = (PathPickVars *)m->pvars;
    fast = 0;
    f = &v->follow;
    if (v->w38 != 0 || v->h1E2 != 0) {
        fast = 1;
    }
    r = fast ? v->radius * 2.0f : v->radius;
    prev = 0;
    next = 0;
    FindNearestTargetMoby(m, &target, r);
    best_d = 10000.0f;
    best_a = 0.0f;
    best = 0;
    if (v->ordered != 0) {
        do {
            if (*idx < f->path->count - 1) {
                *idx = (*idx + f->path->count + f->dir) % f->path->count;
            }
            if (*idx == f->path->count - 1) {
                break;
            }
        } while (f->path->pts[*idx].w != 1.0f);
        return 1;
    }
    last = 0;
    for (i = 0; i < f->path->count; i++) {
        if (v->stops_only == 0 || f->path->pts[i].w == 1.0f) {
            dist = vec_distance_xy(&f->path->pts[i], &m->pos);
            if (dist < best_d) {
                prev = last;
                best_d = dist;
                best = i;
            } else if (last == best) {
                next = i;
            }
            last = i;
        }
    }
    i = best;
    if (i == f->path->count - 1) {
        next = 0;
    } else if (i == 0) {
        prev = f->path->count - 1;
    }
    best_d = 0.0f;
    best = 0;
    if (fast) {
        best_d = 10000.0f;
    }
    *idx = 0;
    for (;;) {
        if (*idx == prev || *idx == i || *idx == next) {
            if (fast) {
                qcopy(&pt, &f->path->pts[*idx]);
                d = FastVecDist(&target, &pt);
                if ((v->stops_only == 0 || pt.f[3] == 1.0f) && d < best_d) {
                    best = *idx;
                    best_d = d;
                }
            } else {
                qcopy(&pt, &f->path->pts[*idx]);
                a = FastDiffRots(fast_atan2(pt.f[0] - m->pos.x, pt.f[1] - m->pos.y),
                                                      fast_atan2(target.pos.f[0] - m->pos.x,
                                                                   target.pos.f[1] - m->pos.y));
                d = FastVecDist(&m->pos, &pt);
                if (v->stops_only == 0 || pt.f[3] == 1.0f) {
                    if (a < 1.5707964f) {
                        if (best_a < a) {
                            best = *idx;
                            best_d = d;
                            best_a = a;
                        }
                    } else if ((d >= 12.0f && (d < best_d || best_d < 12.0f)) || (d < 12.0f && best_d < d)) {
                        best = *idx;
                        best_d = d;
                        best_a = a;
                    }
                }
            }
        }
        *idx = (*idx + f->path->count + f->dir) % f->path->count;
        if (*idx == 0) {
            *idx = best;
            break;
        }
    }
    /* i is reused for the result so it outlives best (keeps retail's copy of the nearest node) */
    i = best != i;
    return i;
}
