/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l01/gameplay/entities/002b96e0.c, FUN_L01_002f3120. */
void water_current_update(Moby *self)
{
    PathCarrierVars *v;
    PePath_F44F8 *path;
    Vec4 nearest;
    Vec4 ahead;
    Vec4 dir;
    Vec4 pull;
    f32 t;
    s32 seg;
    s32 at_end;
    f32 dist;
    f32 limit;
    f32 len;
    f32 cap;
    s32 i;

    v = (void *)self->pvars;
    if (v == 0 || v->path == -1) {
        return;
    }
    path = (PePath_F44F8 *)novalis_paths[v->path];
    if (v->ready == 0) {
        /* store each segment's length in its start point's w */
        v->ready = 1;
        for (i = 0; i < path->count - 1; i++) {
            path->pts[i].f[3] = FastVecDist(&path->pts[i], &path->pts[i + 1]);
        }
        path->pts[i].f[3] = FastVecDist(&path->pts[i], &path->pts[0]);
        self->update_dist = 0xFF;
    }

    if ((u32)(g_hero.state.control_mode - 0x11) >= 2 && g_hero.state.prev_control_mode != 0x11
        && g_hero.state.prev_control_mode != 0x12 && g_hero.state.current != 0x12
        && g_hero.state.prev != 0x12) {
        return;
    }
    find_nearest_path_point(path, &g_hero.motion.pos, &nearest, &t, &seg, 0, 999.0f, 5.0f, 0.0f);
    at_end = Spline_AdvanceByDistance(path, &ahead, &t, &seg, 0, 2.0f);
    dist = vec_distance_xy(&g_hero.motion.pos, &nearest);
    if (v->radius < dist) {
        return;
    }

    if ((u32)(g_hero.state.control_mode - 0x11) < 2) {
        if (g_hero.current_path_dist < dist) {
            return;
        }
        g_hero.current_path_dist = dist;
        if (at_end == 0) {
            FastVecSub(&dir, &ahead, &nearest);
            vec_scale_to_length(&dir, &dir, g_frame_time_sq * 7.0f);
            FastVecAdd(v, v, &dir);
            v->vel.f[2] = 0.0f;
            if (v->max_speed < FastVecLength(v)) {
                vec_scale_to_length(v, v, v->max_speed);
            }
            qcopy(&g_hero.motion.platform_delta, v);
            if (v->pull != 0) {
                FastVecSub(&pull, &nearest, &g_hero.motion.pos);
                pull.f[2] = 0.0f;
                limit = v->max_speed * 0.4f;
                if (limit < FastVecLength(&pull)) {
                    vec_scale_to_length(&pull, &pull, limit);
                }
                FastVecAdd(&g_hero.motion.platform_delta, &g_hero.motion.platform_delta, &pull);
            }
        } else {
            /* past the end: slow down (factor 1 - 0.005 per frame unit) */
            len = FastVecLength(v);
            vec_scale_to_length(v, v, frame_scale * -0.004999995231628418f * len + len);
            qcopy(&g_hero.motion.platform_delta, v);
        }
        if (g_hero.state.control_mode == 0x12 && g_hero.state.prev == g_hero.state.control_mode) {
            if (g_hero.state_timer < scale_ticks(3)) {
                cap = (*(f32 *)&g_frame_time_r) * 1.5f;
                if (cap < g_hero.ground_speed) {
                    g_hero.ground_speed = cap;
                }
                clear_u64_value(&g_hero.motion.momentum);
            }
        }
    } else if ((g_hero.state.prev_control_mode == 0x12 || g_hero.state.prev2_control_mode == 0x12)
               && (u32)(g_hero.state.control_mode - 4) < 2) {
        len = FastVecLength(v);
        vec_scale_to_length(v, v, frame_scale * -0.014999985694885254f * len + len);
        qcopy(&g_hero.motion.platform_delta, v);
        if (g_hero.jump_lockout_timer < scale_ticks(0x23)) {
            g_hero.jump_lockout_timer = scale_ticks(0x23);
        }
    }
}
