/* Floating mine: scales with the camera distance; when hit it explodes (unlocks the first-mine hint
 * once), deletes its four tethers and itself; otherwise it bobs and fades out with height. */
void TetheredMineUpdate(char *m) {
    float dir[4];
    float tmp[4];
    char *d = ((char *)((Moby *)m)->pvars);
    void *hit = MobyGetHitMessage(m, 0x800000, 0);
    float s;
    ((unsigned char *)m)[0xA4] = 0xFF;
    if (((unsigned char *)m)[0x20] == 0) {
        *(float *)(d + 0x170) = ((Moby *)m)->scale;
        *(float *)(d + 0x174) = *(float *)(d + 0xFC);
    }
    {
        float dist = FastVecDist(m + 0x10, camera_pos);
        float lo = *(float *)&novalis_tethered_mine_min_scale;
        float x0 = *(float *)&novalis_tethered_mine_near_distance;
        float k = -((1.0f - lo) / (*(float *)&novalis_tethered_mine_far_distance - x0));
        s = k * dist + (1.0f - k * x0);
        if (1.0f < s) s = 1.0f;
        if (s < lo) s = lo;
    }
    ((Moby *)m)->scale = *(float *)(d + 0x170) * s;
    *(float *)(d + 0xFC) = *(float *)(d + 0x174) * s;
    if (hit != 0) {
        int i;
        int *t;
        if (((unsigned char *)m)[0x20] == 0x65) return;
        if ((&menu_item_enabled_115_k)[1] == 0) {
            (&menu_item_enabled_115_k)[1] = 1;
            PlayBankSound(1, 0, 0);
            ShowBanner(0x53DB, -1);
        }
        FastVecSub(tmp, d + 0xD0, d + 0xE0);
        m[0x20] = 0x65;
        *(u128 *)dir = *(u128 *)tmp;
        spawn_explosion(m, dir, m + 0x10, 0.0f, 0.0f, 0x14, 3, 4, 4.0f, 2.0f, 100000.0f, 3.0f, 1, 15.0f, 1, 1, -1, 0);
        SpawnDebrisMoby(m, dir, s);
        t = (int *)(d + 0x140);
        for (i = 0; i < 4; i++) {
            if (t[i] != -1) {
                DeleteMoby((char *)(*(int *)&novalis_mobys + (t[i] << 8)));
            }
        }
        DeleteMoby(m);
        return;
    }
    if (((unsigned char *)m)[0x20] == 0x65) return;
    gunship_follow_path(m);
    ((Moby *)m)->flags |= 0x1000;
    d[0x2B] = 1;
    d[0x2C] = 0x64;
    if (175.0f <= ((Moby *)m)->pos.z) {
        m[0x23] = 0;
    } else if (125.0f < ((Moby *)m)->pos.z && ((Moby *)m)->pos.z < 175.0f) {
        m[0x23] = truncate_float_to_s32_r((175.0f - ((Moby *)m)->pos.z) * 128.0f / 50.0f);
    } else if (((Moby *)m)->pos.z <= 125.0f) {
        ((unsigned char *)m)[0x23] = 0x80;
    }
}
