/* Spawns a beam moby from an owner, position, direction and colour vectors. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/l01/unclassified_002b96e0.c, FUN_L01_002f68a0. */
BeamMoby *spawn_beam(void *owner, u128_t *pos, u128_t *dir, u128_t *color, int kind) {
    Vec4 p;
    Vec4 d;
    Vec4 c;
    BeamMoby *m;
    BeamVars *v;
    Vec4 *pp;
    Vec4 *pd;
    Vec4 *pc;

    pp = &p;
    pd = &d;
    pc = &c;
    p.q = *pos;
    d.q = *dir;
    c.q = *color;
    m = CreateMoby_b(0x2AE);
    if (m != 0) {
        v = (BeamVars *)m->vars;
        v->owner = owner;
        m->w40 = 0;
        m->b30 = 0xFF;
        m->h32 = 0xFF;
        m->b31 = 1;
        m->scale = m->scale * 0.25f;
        m->rot_x = -fast_atan2(vec_length_xy(pd), ((float *)pd)[2]);
        m->rot_z = fast_atan2(((float *)&d)[0], ((float *)pd)[1]);
        qcopy(&m->pos, pp);
        qcopy(&v->dir, pd);
        qcopy(&v->color, pc);
        v->kind = kind;
        v->len = FastVecLength(pd);
        spawn_source_attached_fading_effect_particle((char *)m, 0x2F4F7F7F, scale_ticks(0x78), -1, 420000.0f);
        spawn_source_attached_fading_effect_particle((char *)m, 0x4F6F7F7F, scale_ticks(0x78), -1, 210000.0f);
        Moby_PlaySound(0, 0, (int)m);
        moby_build_matrix(m);
    }
    return m;
}
