// Emitter update: ticks timers, occasionally bursts a smoke puff and spawns two drifting smoke particles per frame. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/l01/unclassified_002b96e0.c, FUN_L01_002f8c58.
void update_rising_particle_and_debris_emitter(SteamMoby *m) {
    SteamVars *v;
    SteamColors colors;
    Vec4 vel;
    Vec4 pos;
    Vec4 puff;
    SteamParticle *p;
    float r;
    float ang;
    float size;
    int life;
    int i;

    v = m->pvars;
    FastDecTimer(&v->puff_timer);
    FastDecTimer(&v->burst_timer);
    if (v->active == 0) {
        return;
    }
    if (fast_dec_timer(v)) {
        v->puff_timer = scale_ticks(0x78);
    }
    if (v->burst_timer == 0 && random_integer_below(100) < 5) {
        colors = novalis_rising_emitter_debris_colors;
        pos.q = 0;
        pos.f[0] = random_float_between(g_frame_time * -0.5f, g_frame_time * 0.5f);
        pos.f[1] = random_float_between(g_frame_time * -0.5f, g_frame_time * 0.5f);
        vel.q = pos.q;
        r = random_float_between(0.0f, 0.25f);
        ang = random_angle_radians();
        pos.f[0] = FastCos(ang) * r;
        pos.f[1] = FastSin(ang) * r;
        pos.f[2] = 0.0f;
        FastVecAdd(&pos, &pos, &m->pos);
        pos.f[2] += v->height;
        spawn_debris_moby(&pos, &vel, colors.c[random_integer_below(3)], rand_range(0xB4, 0x12C), 0.05f, 1.0f, 1.0f, 0.75f, 0);
    }
    for (i = 0; i < 2; i++) {
        colors = novalis_rising_emitter_puff_colors;
        puff.q = 0;
        puff.f[0] = random_float_between(g_frame_time * -0.5f, g_frame_time * 0.5f);
        puff.f[1] = random_float_between(g_frame_time * -0.5f, g_frame_time * 0.5f);
        puff.f[2] = random_float_between(g_frame_time * 0.0f, g_frame_time * 3.0f);
        vel.q = puff.q;
        r = random_float_between(0.0f, 0.25f);
        ang = random_angle_radians();
        puff.f[0] = FastCos(ang) * r;
        puff.f[1] = FastSin(ang) * r;
        puff.f[2] = 0.0f;
        FastVecAdd(&puff, &puff, &m->pos);
        r *= g_frame_time;
        r *= 8.0f;
        puff.f[2] += v->height;
        vel.f[2] += r;
        size = random_float_between(70000.0f, 140000.0f);
        life = scale_ticks(0xB4);
        p = (SteamParticle *)mine_debris(size, (char *)&puff, (char *)&vel, 0x0F081020, 0x00081020, life, colors.c[random_integer_below(3)]);
        if (p != 0) {
            p->floor_z = m->pos.f[2] - 0.5f;
        }
    }
}
